import json
from collections import Counter

def solve_grid_clean(grid):
    """Fill enclosed background regions with structure_color - background."""
    rows, cols = len(grid), len(grid[0])

    # Determine background (most frequent)
    bg_counts = Counter()
    for r in range(rows):
        for c in range(cols):
            bg_counts[grid[r][c]] += 1
    background = bg_counts.most_common(1)[0][0]

    # Structure colors (all non-background)
    structure_colors = set()
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] != background:
                structure_colors.add(grid[r][c])

    # Flood fill from edge to find all cells reachable from boundary
    reached_edge = [[False]*cols for _ in range(rows)]
    queue = []

    # Start from all edge cells with background color
    for r in range(rows):
        if grid[r][0] == background:
            reached_edge[r][0] = True
            queue.append((r, 0))
        if grid[r][cols-1] == background:
            reached_edge[r][cols-1] = True
            queue.append((r, cols-1))
    for c in range(cols):
        if grid[0][c] == background:
            reached_edge[0][c] = True
            queue.append((0, c))
        if grid[rows-1][c] == background:
            reached_edge[rows-1][c] = True
            queue.append((rows-1, c))

    # BFS
    while queue:
        r, c = queue.pop(0)
        for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
            nr, nc = r+dr, c+dc
            if 0 <= nr < rows and 0 <= nc < cols and not reached_edge[nr][nc]:
                if grid[nr][nc] == background:
                    reached_edge[nr][nc] = True
                    queue.append((nr, nc))

    # Fill enclosed regions
    output = [row[:] for row in grid]

    # Calculate fill color: structure_color - background
    if len(structure_colors) == 1:
        structure = list(structure_colors)[0]
        fill_color = structure - background
    else:
        fill_color = None

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == background and not reached_edge[r][c]:
                if fill_color is not None:
                    output[r][c] = fill_color

    return output, reached_edge, fill_color,.structure_colors

