def transform(input_grid):
    height = len(input_grid)
    if not input_grid:
        return []
    width = len(input_grid[0])
    if not width:
        return [[] for _ in range(height)]

    result = [row[:] for row in input_grid]
    background = result[0][0]

    visited = set()

    for r in range(height):
        for c in range(width):
            if (r, c) in visited:
                continue
            if result[r][c] == background:
                continue

            val = result[r][c]
            cells = []
            queue = [(r, c)]
            visited.add((r, c))

            while queue:
                cr, cc = queue.pop(0)
                cells.append((cr, cc))
                for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                    nr, nc = cr + dr, cc + dc
                    if (0 <= nr < height and 0 <= nc < width
                        and (nr, nc) not in visited and result[nr][nc] == val):
                        visited.add((nr, nc))
                        queue.append((nr, nc))

            if len(cells) < 5:
                continue

            rows_s = sorted(set(x[0] for x in cells))
            cols_s = sorted(set(x[1] for x in cells))
            top, bottom = rows_s[0], rows_s[-1]
            left, right = cols_s[0], cols_s[-1]

            is_frame = True
            for rf in [top, bottom]:
                for cf in range(left, right + 1):
                    if result[rf][cf] != val:
                        is_frame = False
                        break
                if not is_frame:
                    break
            if not is_frame:
                continue

            for cf in [left, right]:
                for rf in range(top + 1, bottom):
                    if result[rf][cf] != val:
                        is_frame = False
                        break
                if not is_frame:
                    break
            if not is_frame:
                continue

            inner_top, inner_bottom = top + 1, bottom - 1
            inner_left, inner_right = left + 1, right - 1

            if inner_top > inner_bottom or inner_left > inner_right:
                continue

            inner_height = inner_bottom - inner_top + 1
            inner_width = inner_right - inner_left + 1

            is_square = (inner_height == inner_width)
            fill_val = 7 if (is_square and inner_height % 2 == 1) else 2

